FUNCTION_BLOCK FB_NestedLoopControl
VAR
    i : INT;
    j : INT;
    flag : BOOL;
    count : INT := 0;
    some_var : INT;
END_VAR

// Main execution of the function block
FOR i := 0 TO 10 DO
    // Check if the flag is TRUE, if so, exit the loop
    IF flag THEN
        EXIT; // Exit the outer loop if the flag is TRUE
    END_IF;

    // Inner loop iterating from 10 to 100 with a step size of 2
    FOR j := 10 TO 100 BY 2 DO
        // Increment the count for each iteration of the inner loop
        count := count + 1;

        // Check if the count exceeds the expected maximum of iterations
        IF count > 460 THEN // 46 iterations (11 * 46 = 506)
            count := 460; // Cap the count to the maximum
            EXIT; // Exit the inner loop if the maximum is reached
        END_IF;

        // Check if the flag is TRUE, if so, exit the inner loop
        IF flag THEN
            EXIT; // Exit the inner loop if the flag is TRUE
        END_IF;

        // Perform any additional operations with some_var if needed
        // some_var := ...; // Example operation
    END_FOR;
END_FOR;

END_FUNCTION_BLOCK
